create function pg_temp.fail_audit() returns trigger language plpgsql as $$ begin raise exception 'Injected audit failure' using errcode='P0001'; end; $$;
create trigger test_fail_audit before insert on public.audit_log for each row execute function pg_temp.fail_audit();
